// Blink without delay(): millis() timing, so loop() never stops and can
// read buttons, sensors and serial while the LED blinks.
const int ledPin = LED_BUILTIN;
const unsigned long interval = 500;   // ms between changes

unsigned long lastChange = 0;         // millis() needs an unsigned long
bool ledOn = false;

void setup() {
  pinMode(ledPin, OUTPUT);
}

void loop() {
  unsigned long now = millis();
  if (now - lastChange >= interval) {  // subtracting stays right when millis() wraps around
