  bool startPressed = P1.readDiscrete(inSlot, 1);        // NO: on while pressed
  bool stopPressed = !P1.readDiscrete(inSlot, 2);        // NC: the input is OFF while Stop is pressed
  bool overloadTripped = !P1.readDiscrete(inSlot, 3);    // NC: the input is OFF when the overload trips
  // the motor runs while it is started or running, and stops while Stop is pressed or the overload trips
  running = (startPressed || running) && !stopPressed && !overloadTripped;
  P1.writeDiscrete(running, outSlot, 1);
  P1.writeDiscrete(running, outSlot, 2);
}
