// Ohm's law and power: give any two of V, I, R, P and get all four.
function solve(g) {
  const { V, I, R, P } = g;
  if (V !== undefined && I !== undefined) return { V, I, R: V / I, P: V * I };
  if (V !== undefined && R !== undefined) return { V, I: V / R, R, P: V * V / R };
  if (I !== undefined && R !== undefined) return { V: I * R, I, R, P: I * I * R };
  if (P !== undefined && V !== undefined) return { V, I: P / V, R: V * V / P, P };
  if (P !== undefined && I !== undefined) return { V: P / I, I, R: P / (I * I), P };
  if (P !== undefined && R !== undefined) return { V: Math.sqrt(P * R), I: Math.sqrt(P / R), R, P };
  throw new Error("give two of V, I, R, P");
}

