// A push button toggles the LED, debounced.
// Wiring: button between pin 2 and GND (INPUT_PULLUP: no resistor needed;
// the pin reads LOW while pressed).
const int buttonPin = 2;
const int ledPin = LED_BUILTIN;
const unsigned long debounceMs = 30;

int stableState = HIGH;        // the last settled reading
int lastReading = HIGH;
unsigned long lastFlip = 0;
bool ledOn = false;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);
}

void loop() {
  int reading = digitalRead(buttonPin);
  if (reading != lastReading) {          // contacts bounce: restart the wait
    lastFlip = millis();
    lastReading = reading;
  }
  if (millis() - lastFlip >= debounceMs && reading != stableState) {
    stableState = reading;
    if (stableState == LOW) {            // just pressed
      ledOn = !ledOn;
      digitalWrite(ledPin, ledOn ? HIGH : LOW);
    }
  }
}
>>>
